            {
                string[] six = { "guy762_MNCHelmet", "guy762_MidBattleArmor_mando", "guy762_MandoArmor_battle", "guy762_MandoArmor_assault", "guy762_MandoArmor_supercom", "guy762_MandoHelmet_supercom" };
